import { BaseElement } from '../common/base-element';
import { fetchProgress, type CampaignProgress } from './api';
import { mountCountdown } from './format';
import { progressBarHtml } from './progress-bar-html';
import { cssImageUrl, escapeHtml } from './safe';
import { listingStyles } from './styles/listing';
import { progressStyles } from './styles/progress';

const INTRO_TEXT =
  'Campaigns are pages anyone in our community can start to raise money toward a specific goal. ' +
  'Below are the campaigns currently active — jump in and support one, or start your own.';

/**
 * <rg-campaign-listing>: the body of /fundraising-campaigns. An intro with a "Start a campaign"
 * button, and a grid of tiles (image, name, progress, countdown) from one `campaign_progress(null)`
 * call. It replaces Squarespace's native product grid, which the site loader hides.
 * Its layout inside Squarespace's content track is set by the page-level styles, not here.
 */
export class RgCampaignListing extends BaseElement {
  private stops: Array<() => void> = [];

  constructor() {
    super(`:host { display: block; }\n${progressStyles}\n${listingStyles}`);
  }

  connectedCallback(): void {
    this.setHtml(`
      <div class="cg-intro">
        <p class="cg-intro-text">${escapeHtml(INTRO_TEXT)}</p>
        <a class="cg-intro-cta" href="/new-fundraising-campaign">Start a campaign →</a>
      </div>
      <div class="cg-grid"></div>`);
    fetchProgress(null)
      .then((rows) => this.renderTiles(rows))
      .catch((err) => console.error('Failed to load campaign grid:', err));
  }

  disconnectedCallback(): void {
    this.stops.forEach((stop) => stop());
    this.stops = [];
  }

  private renderTiles(rows: CampaignProgress[]): void {
    const grid = this.$('.cg-grid');
    if (!grid) return;
    for (const row of rows) {
      const tile = document.createElement('a');
      tile.className = 'cg-tile';
      tile.href = `/fundraising-campaigns/p/${encodeURIComponent(row.slug)}`;
      tile.innerHTML =
        `<div class="cg-tile-image"></div>` +
        `<div class="cg-tile-body"><h3 class="cg-tile-title">${escapeHtml(row.name)}</h3>` +
        `<div class="cg-tile-progress">${progressBarHtml(row.raised_cents, row.goal_cents)}</div>` +
        `<div class="cg-tile-countdown"></div></div>`;
      const image = cssImageUrl(row.image_url);
      if (image) tile.querySelector<HTMLElement>('.cg-tile-image')!.style.backgroundImage = image;
      grid.appendChild(tile);
      this.stops.push(mountCountdown(tile.querySelector('.cg-tile-countdown'), row.target_date, 60000));
    }
  }
}

if (!customElements.get('rg-campaign-listing')) customElements.define('rg-campaign-listing', RgCampaignListing);
